#!/usr/bin/env bash
set -euo pipefail
cd /usr/share/elasticsearch

# Passwords generated by the initializer are alphanumeric, avoiding shell/JSON ambiguity.
[[ "${ELASTIC_PASSWORD}" =~ ^[A-Za-z0-9]{24,}$ ]] || { echo 'Use the generated ELASTIC_PASSWORD.'; exit 1; }
[[ "${KIBANA_PASSWORD}" =~ ^[A-Za-z0-9]{24,}$ ]] || { echo 'Use the generated KIBANA_PASSWORD.'; exit 1; }
[[ "${LAB_SERVER_IP}" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] || { echo 'Set LAB_SERVER_IP to a private IPv4 address.'; exit 1; }

if [ ! -f config/certs/ca/ca.crt ]; then
  bin/elasticsearch-certutil ca --silent --pem --out config/certs/ca.zip
  unzip -q config/certs/ca.zip -d config/certs
fi

if [ ! -f config/certs/es01/es01.crt ]; then
  cat > config/certs/instances.yml <<EOF
instances:
  - name: es01
    dns: [es01, localhost]
    ip: [127.0.0.1, ${LAB_SERVER_IP}]
  - name: kibana
    dns: [kibana, localhost]
    ip: [127.0.0.1, ${LAB_SERVER_IP}]
  - name: fleet-server
    dns: [fleet-server, localhost]
    ip: [127.0.0.1, ${LAB_SERVER_IP}]
EOF
  bin/elasticsearch-certutil cert --silent --pem \
    --in config/certs/instances.yml --out config/certs/instances.zip \
    --ca-cert config/certs/ca/ca.crt --ca-key config/certs/ca/ca.key
  unzip -q config/certs/instances.zip -d config/certs
fi

# Elastic's container user is in group 0. Other services mount this volume read-only.
chown -R root:root config/certs
find config/certs -type d -exec chmod 750 {} \;
find config/certs -type f -exec chmod 640 {} \;

ready=0
for attempt in $(seq 1 120); do
  if curl -fsS --cacert config/certs/ca/ca.crt \
      -u "elastic:${ELASTIC_PASSWORD}" https://es01:9200 >/dev/null 2>&1; then
    ready=1
    break
  fi
  sleep 2
done
[ "$ready" = 1 ] || { echo 'Elasticsearch did not become ready; inspect its logs.'; exit 1; }

curl -fsS --cacert config/certs/ca/ca.crt \
  -u "elastic:${ELASTIC_PASSWORD}" \
  -H 'Content-Type: application/json' \
  -X POST https://es01:9200/_security/user/kibana_system/_password \
  -d "{\"password\":\"${KIBANA_PASSWORD}\"}" >/dev/null
echo 'Certificates and Kibana service password are prepared.'
